"""Single-experiment review workspace rendered by the local Research Hub."""

from __future__ import annotations

import json
from html import escape
from typing import Any


def render_experiment_page(
    experiment: dict[str, Any],
    *,
    live: bool = True,
    base_path: str = "",
) -> str:
    """Render one complete report/editor page for a discovered bundle.

    The page keeps the bundle's HTML as the full-report view, while the
    responsibility-repository Markdown is the editable source.  Images,
    videos and nested HTML are served through the Hub's range-capable route.
    """

    normalized_base = "/" + base_path.strip("/") if base_path.strip("/") else ""
    payload = json.dumps(experiment, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    mode = "live" if live else "static"
    return _TEMPLATE.replace("__EXPERIMENT__", payload).replace("__BASE_PATH__", json.dumps(normalized_base)).replace("__MODE__", mode)


_TEMPLATE = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>实验校阅</title>
<style>
:root{--bg:#f3f6fb;--surface:#fff;--ink:#172033;--muted:#60708a;--line:#d5deeb;--accent:#275dad;--ok:#147d45;--warn:#9a6200}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1680px;margin:auto;padding:16px}.hero,.panel{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px;margin-bottom:12px}.hero{display:flex;justify-content:space-between;gap:16px;align-items:start}.muted{color:var(--muted)}.path{font:12px/1.4 ui-monospace,SFMono-Regular,monospace;overflow-wrap:anywhere;color:var(--muted)}a{color:var(--accent)}button{font:inherit;border:1px solid var(--accent);background:var(--accent);color:#fff;border-radius:7px;padding:7px 10px;cursor:pointer}button.secondary{color:var(--accent);background:transparent}button:disabled{opacity:.5;cursor:not-allowed}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.layout{display:grid;grid-template-columns:minmax(320px,1.05fr) minmax(420px,1.35fr) minmax(280px,.8fr);gap:12px;align-items:start}.sticky{position:sticky;top:10px}.editor{width:100%;min-height:64vh;resize:vertical;font:13px/1.5 ui-monospace,SFMono-Regular,monospace;border:1px solid var(--line);border-radius:8px;padding:12px;background:#fff;color:var(--ink)}.frame{width:100%;height:74vh;border:1px solid var(--line);border-radius:8px;background:#fff}.diff{max-height:220px;overflow:auto;white-space:pre-wrap;background:#101820;color:#eaf1f9;border-radius:8px;padding:10px;font:12px/1.45 ui-monospace,SFMono-Regular,monospace}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.metric{border:1px solid var(--line);border-radius:8px;padding:8px;overflow-wrap:anywhere}.metric b{display:block;font-size:18px}.media-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}.media-card{border:1px solid var(--line);border-radius:8px;padding:8px;background:#fafcff}.media-card img,.media-card video,.media-card iframe{width:100%;max-height:260px;object-fit:contain;border:1px solid var(--line);background:#fff}.media-card video{height:220px}.media-card iframe{height:220px}.media-card audio{width:100%}.badge{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 8px;font-size:12px;margin:2px}.badge.ok{color:var(--ok);border-color:#afd7bc}.badge.warn{color:var(--warn);border-color:#e4c587}.section-title{margin:16px 0 8px;border-bottom:1px solid var(--line);padding-bottom:5px}@media(max-width:1180px){.layout{grid-template-columns:1fr 1fr}.layout>aside{grid-column:1/-1;position:static}}@media(max-width:760px){main{padding:8px}.hero,.layout{display:block}.layout>*+*{margin-top:12px}.sticky{position:static}.frame{height:58vh}.editor{min-height:45vh}}
</style></head><body data-mode="__MODE__"><main>
<header class="hero"><div><p><a id="backLink">← Research Hub 总览</a></p><h1 id="title">实验校阅</h1><p id="run" class="path"></p><p id="meta" class="muted"></p></div><div class="actions"><a id="taskLink" target="_blank" rel="noopener">ClearML Task</a><button id="publish" title="创建新的 ClearML 历史快照">发布新 ClearML 快照</button></div></header>
<section class="panel"><div id="notice" class="muted">加载实验 bundle…</div></section>
<div class="layout">
<section class="panel"><h2>实验文档（canonical Markdown）</h2><p id="docPath" class="path"></p><textarea id="editor" class="editor" spellcheck="false" disabled></textarea><div class="actions"><button id="preview" disabled>检查并预览 diff</button><button id="save" disabled>保存并刷新预览</button><button id="attach" class="secondary" disabled>上传媒体</button><input id="attachment" type="file" hidden></div><pre id="diff" class="diff">当前页面只读加载中…</pre></section>
<section class="panel"><h2>完整 HTML 校阅报告</h2><p class="muted">这是 bundle 的 report.html 预览；图片、视频、子 HTML 通过同一 Hub 地址加载。当前编辑入口是左侧 canonical Markdown，保存后重新生成预览；此处不会直接改写历史 HTML artifact。</p><iframe id="report" class="frame" title="完整 HTML 校阅报告" sandbox="allow-scripts allow-same-origin"></iframe><h2 class="section-title">编辑后 canonical 文档预览</h2><iframe id="sourcePreview" class="frame" title="canonical Markdown 预览" sandbox="allow-scripts allow-same-origin"></iframe><h2 class="section-title">ClearML 原生任务视图</h2><p class="muted">任务状态、日志、Scalars 和 Debug Samples 直接显示在本页；不需要切换窗口。</p><iframe id="clearmlTask" class="frame" title="ClearML 原生任务视图" sandbox="allow-forms allow-modals allow-popups allow-scripts allow-same-origin"></iframe></section>
<aside><section class="panel sticky"><h2>状态与指标</h2><div id="status"></div><div id="metrics" class="metrics"></div><p id="fingerprints" class="path"></p></section><section class="panel"><h2>证据文件</h2><div id="files"></div></section></aside>
</div><section class="panel"><h2>章节媒体与人工校阅</h2><div id="media"></div></section>
</main><script id="experiment-data" type="application/json">__EXPERIMENT__</script>
<script>
(()=>{const initial=JSON.parse(document.getElementById('experiment-data').textContent),basePath=__BASE_PATH__,live=document.body.dataset.mode==='live';const token=new URLSearchParams(location.search).get('token')||'';const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const path=p=>{const clean=p.startsWith('/')?p:'/'.concat(p);return (basePath||'')+clean};const api=async(p,opts={})=>{const headers={...(opts.headers||{})};if(token)headers['X-Research-Hub-Token']=token;const r=await fetch(path(p),{...opts,headers});const b=await r.json().catch(()=>({error:r.statusText}));if(!r.ok)throw new Error(b.error||r.statusText);return b};const fileUrl=relative=>path('/api/experiments/'+encodeURIComponent(initial.id)+'/files/'+relative.split('/').map(encodeURIComponent).join('/'));const setText=(id,v)=>$(id).textContent=v||'';let experiment=initial,doc=null,previewToken=null;
function renderStatus(){setText('title',experiment.title);setText('run','run_id: '+experiment.run_id);setText('meta',(experiment.task_id?'ClearML Task '+experiment.task_id+' · ':'')+(experiment.canonical_document_path?'已绑定 canonical 文档':'未绑定 canonical 文档'));$('taskLink').href=experiment.task_url||'#';$('taskLink').style.display=experiment.task_url?'inline':'none';$('clearmlTask').src=experiment.task_url||'about:blank';$('clearmlTask').style.display=experiment.task_url?'block':'none';$('publish').disabled=!live;setText('docPath',experiment.canonical_document_path||'当前 bundle 没有可写 canonical Markdown；请在责任仓新增记录后重新索引。');$('status').innerHTML='<span class="badge '+(experiment.task_id?'ok':'warn')+'">'+esc(experiment.task_id?'ClearML linked':'local bundle')+'</span><span class="badge">'+esc((experiment.files||[]).length)+' 文件</span><span class="badge">'+esc((experiment.media||[]).length)+' 媒体</span>';$('fingerprints').textContent=experiment.linkage?.run_id?'linkage run_id: '+experiment.linkage.run_id:'';}
function renderFiles(){const files=experiment.files||[];$('files').innerHTML=files.map(f=>'<p><a href="'+fileUrl(f.relative_path)+'" target="_blank" rel="noopener">'+esc(f.relative_path)+'</a><br><span class="path">'+(f.size_bytes/1024).toFixed(1)+' KiB</span></p>').join('')||'<p class="muted">没有文件。</p>';}
function renderMedia(){const groups={};for(const item of experiment.media||[])(groups[item.section]??=[]).push(item);$('media').innerHTML=Object.entries(groups).map(([section,items])=>'<h3 class="section-title">'+esc(section)+'</h3><div class="media-grid">'+items.map(item=>{const u=fileUrl(item.relative_path),e=(item.extension||'').toLowerCase(),safe=esc(u);let body;if(['.png','.jpg','.jpeg','.gif','.webp','.svg'].includes(e))body='<img loading="lazy" src="'+safe+'" alt="'+esc(item.title)+'">';else if(['.mp4','.webm','.mov','.mkv'].includes(e))body='<video controls preload="metadata" src="'+safe+'"></video>';else if(['.mp3','.wav','.ogg'].includes(e))body='<audio controls src="'+safe+'"></audio>';else if(e==='.html')body='<iframe loading="lazy" src="'+safe+'" title="'+esc(item.title)+'" sandbox="allow-scripts allow-same-origin"></iframe>';else body='<a href="'+safe+'" target="_blank">打开产物</a>';return '<article class="media-card">'+body+'<p>'+esc(item.title)+'</p><span class="path">'+esc(item.relative_path)+'</span></article>'}).join('')+'</div>').join('')||'<p class="muted">manifest 没有章节媒体。</p>';}
function flatten(value,prefix,out){if(typeof value==='number'&&Number.isFinite(value)){out.push([prefix,value]);return}if(value&&typeof value==='object'&&!Array.isArray(value))for(const [k,v] of Object.entries(value))flatten(v,prefix?prefix+'.'+k:k,out);}
async function renderMetrics(){const score=(experiment.files||[]).find(f=>f.relative_path==='scorecard.json');if(!score){$('metrics').innerHTML='<p class="muted">没有 scorecard.json。</p>';return}try{const data=await (await fetch(fileUrl(score.relative_path))).json();const rows=[];flatten(data,'',rows);$('metrics').innerHTML=rows.slice(0,40).map(([k,v])=>'<div class="metric"><span class="muted">'+esc(k)+'</span><b>'+esc(typeof v==='number'?String(Number(v.toPrecision(8))):String(v))+'</b></div>').join('')}catch(error){$('metrics').innerHTML='<p class="muted">指标读取失败：'+esc(error.message)+'</p>'}}
async function loadDocument(){if(!experiment.canonical_document_id){$('editor').disabled=true;$('preview').disabled=true;$('save').disabled=true;return}try{doc=await api('/api/documents/'+encodeURIComponent(experiment.canonical_document_id));$('editor').value=doc.content;$('editor').disabled=false;$('preview').disabled=false;$('save').disabled=true;$('attach').disabled=false;previewToken=null;setText('diff','编辑后点击“检查并预览 diff”。');if(doc.rendered_href)$('sourcePreview').src=path('/api/hub-state/'+encodeURIComponent(doc.rendered_href));}catch(error){setText('diff','文档加载失败：'+error.message)}}
async function refresh(){experiment=await api('/api/experiments/'+encodeURIComponent(initial.id));renderStatus();renderFiles();renderMedia();await renderMetrics();await loadDocument();const htmlFiles=(experiment.files||[]).filter(f=>(f.extension||'').toLowerCase()==='.html');const report=['report.html','experiment_record_rendered.html','review.html'].map(name=>htmlFiles.find(f=>f.relative_path===name)).find(Boolean)||htmlFiles[0];if(report)$('report').src=fileUrl(report.relative_path);else if(doc?.rendered_href)$('report').src=path('/api/hub-state/'+encodeURIComponent(doc.rendered_href));}
async function preview(){if(!doc)return;try{const r=await api('/api/documents/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:doc.id,base_sha256:doc.sha256,content:$('editor').value})});previewToken=r.preview_token;setText('diff',(r.validation_errors.length?'校验失败：\n'+r.validation_errors.join('\n')+'\n\n':'校验通过。\n\n')+r.diff);$('save').disabled=!r.ok}catch(error){setText('diff',error.message);$('save').disabled=true}}
async function save(){if(!doc)return;if(!previewToken){await preview();if(!previewToken)return}try{const r=await api('/api/documents/'+encodeURIComponent(doc.id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({base_sha256:doc.sha256,content:$('editor').value,preview_token:previewToken})});doc.sha256=r.sha256;doc.content=$('editor').value;previewToken=null;$('save').disabled=true;await api('/api/reindex',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await refresh();setText('diff','已保存 canonical Markdown，并重新生成 Hub 预览。备份：'+r.backup_path)}catch(error){setText('diff','保存失败：'+error.message)}}
async function publish(){if(!live)return;setText('notice','正在创建新的 ClearML 快照，请等待上传完成…');$('publish').disabled=true;try{const r=await api('/api/experiments/'+encodeURIComponent(initial.id)+'/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});setText('notice','已创建 ClearML 快照：'+(r.task_id||r.message||'完成'));if(r.task_url){$('taskLink').href=r.task_url;$('taskLink').style.display='inline'}}catch(error){setText('notice','发布失败：'+error.message)}finally{$('publish').disabled=false}}
async function uploadAttachment(event){const file=event.target.files[0];if(!file||!doc)return;try{const r=await api('/api/attachments?document_id='+encodeURIComponent(doc.id),{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-Filename':encodeURIComponent(file.name)},body:file});const editor=$('editor');editor.setRangeText(r.markdown_link,editor.selectionStart,editor.selectionEnd,'end');previewToken=null;$('save').disabled=false;setText('diff','媒体已存入 Hub 受控目录并插入 Markdown 链接；请检查后保存。')}catch(error){setText('diff','媒体上传失败：'+error.message)}finally{event.target.value=''}}
function init(){ $('backLink').href=basePath||'/'; $('preview').onclick=preview;$('save').onclick=save;$('publish').onclick=publish;$('attach').onclick=()=>$('attachment').click();$('attachment').onchange=uploadAttachment;renderStatus();refresh().catch(error=>setText('notice','实验加载失败：'+error.message));}init();})();
</script></body></html>"""
